/* Game data from the user's ROM: tables generated by tools/port/gen_data.py
 * and tools/port/pp_assets.py, consumed by port/host_assets.c. */
#ifndef PORT_PORT_ASSETS_H
#define PORT_PORT_ASSETS_H

#include <stdint.h>

/* A pointer slot inside a data blob: receives target + addend at start. */
struct PortReloc {
    unsigned char *where;
    const unsigned char *target;
    uint32_t addend;
};

/* One contiguous block of ROM data (a section of an assembler data file). */
struct PortBlob {
    unsigned char *dst;
    uint32_t size;
    uint64_t hash;       /* FNV-1a 64 of the contents with the holes zeroed */
    uint64_t key1;       /* 8 bytes at keyOff1 (4-aligned, hole-free), probe */
    int32_t keyOff1;     /* -1: no probe window; -2: constant block, key1 = fill byte */
    uint64_t key2;
    int32_t keyOff2;
    uint32_t romAddr;    /* 0x08xxxxxx if the decomp states it, else 0 */
    const uint32_t *holes; /* (offset, length) pairs, sorted */
    uint32_t holeCount;
    const uint64_t *chunks; /* FNV-1a 64 per PORT_CHUNK bytes (blocks >= 2 chunks) */
    uint32_t chunkCount;
    /* the block's parts between its global symbols (files, tables): looked
     * for one by one when the whole block is not in the ROM */
    const struct PortBlob *children;
    uint32_t childCount;
    const char *name;
};

#define PORT_CHUNK 512

extern const struct PortReloc gPortRelocs[];
extern const unsigned gPortRelocCount;
extern const struct PortBlob gPortBlobs[];
extern const unsigned gPortBlobCount;

/* C arrays (INCBIN) registered by the generated per-file functions. */
void PortAsset_Add(const char *name, void *dst, unsigned size, unsigned long long hash,
                   unsigned long long key1, int keyOff1, unsigned long long key2, int keyOff2,
                   const unsigned long long *chunks, unsigned chunkCount);
/* After Port_LoadRom: blocks taken over only partly (another ROM version)
 * and blocks not found at all. */
extern unsigned gPortAssetsPartial, gPortAssetsMissing;
void PortAssets_RegisterAll(void);

#endif
